  ('2', '4', '2', 'Nayapul to Tikhedhunga', 'Drive to Nayapul (1.5hr), begin trek through Birethanti village.', 'Guesthouse', '["Breakfast","Lunch","Dinner"]', '13', '1540', '720', NULL, NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 14:38:49'),
  ('3', '4', '3', 'Tikhedhunga to Ghorepani', 'Steep climb through rhododendron forest. Sunrise views of Dhaulagiri.', 'Teahouse', '["Breakfast","Lunch","Dinner"]', '12', '2874', '1334', NULL, NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 14:38:49'),
  ('4', '4', '4', 'Poon Hill Sunrise & Tadapani', 'Pre-dawn climb to Poon Hill (3,210m) for panoramic sunrise. Trek to Tadapani.', 'Teahouse', '["Breakfast","Lunch","Dinner"]', '10', '2630', '336', NULL, NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 14:38:49'),
  ('5', '4', '5', 'Tadapani to Chhomrong', 'Trek through oak forests to the Gurung village of Chhomrong.', 'Teahouse', '["Breakfast","Lunch","Dinner"]', '9', '2170', NULL, NULL, NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 14:38:49'),
