  ('7', '4', '7', 'Dovan to Deurali', 'Trek through Himalaya Hotel and Hinko Cave area. Glacier views.', 'Teahouse', '["Breakfast","Lunch","Dinner"]', '7', '3230', '630', NULL, NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 14:38:49'),
  ('8', '4', '8', 'Deurali to Annapurna Base Camp', 'Final push to the glacier amphitheatre at 4,130m. Incredible 360° views.', 'Teahouse', '["Breakfast","Lunch","Dinner"]', '9', '4130', '900', NULL, NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 14:38:49'),
  ('9', '4', '9', 'ABC to Bamboo via Jhinu Hot Springs', 'Descend fast, stop at natural hot springs at Jhinu for a soak.', 'Guesthouse', '["Breakfast","Lunch","Dinner"]', '16', '2310', NULL, NULL, NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 14:38:49'),
  ('10', '4', '10', 'Bamboo to Chhomrong to Sinuwa', 'Continue descent through familiar terrain.', 'Teahouse', '["Breakfast","Lunch","Dinner"]', '10', '2360', NULL, NULL, NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 14:38:49'),
  ('11', '4', '11', 'Sinuwa to Nayapul', 'Long descent day. Drive to Pokhara on arrival.', 'Hotel', '["Breakfast","Lunch"]', '18', '820', NULL, NULL, NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 14:38:49'),
