INSERT INTO `packages` (`id`, `type`, `name`, `slug`, `location`, `region`, `short_description`, `description`, `cover_image`, `gallery`, `price_per_person`, `price_group`, `duration_days`, `duration_nights`, `min_group_size`, `max_group_size`, `difficulty`, `max_altitude_m`, `best_season`, `start_point`, `end_point`, `highlights`, `included`, `excluded`, `requirements`, `faqs`, `featured`, `active`, `views`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `country_id`) VALUES
  ('1', 'pilgrimage_tour', 'Muktinath Tour and Pilgrimage', 'bungee-jump-last-resort', 'Jomsom, Muktinath', 'Gandaki Province', 'Pilgrimage site in 4000m — one of Asia\'s best pilgrimage for Hindu and Buddhist', '<p>Best Pilgrimage Site in Nepal</p>', NULL, NULL, '120', NULL, '1', '0', '1', '15', 'easy', NULL, 'Year-round', NULL, NULL, '["Transport from Kathmandu"]', '["Return transport KTM","Harness & equipment","Safety briefing"]', '["Personal insurance","Meals","Accommodation"]', NULL, NULL, '1', '1', '6', NULL, NULL, '2026-04-26 14:38:49', '2026-04-30 09:04:13', NULL),
  ('2', 'adventure', 'White Water Rafting — Trishuli River', 'rafting-trishuli-river', 'Trishuli, Nuwakot', 'Bagmati Province', 'Grade 3–4 rapids on Nepal\'s most popular rafting river. Full day from Kathmandu.', '<p>The Trishuli River offers the perfect introduction to white water rafting. Grade 3–4 rapids provide genuine excitement while remaining accessible to beginners. The river cuts through green hills with views of distant Himalayan peaks.</p>', NULL, NULL, '55', NULL, '1', '0', '1', '15', 'moderate', NULL, 'Oct-May', NULL, NULL, '["Grade 3\\u20134 rapids","Himalayan views","Professional guides","All equipment included"]', '["Transport from KTM","Rafting equipment","Guide","Lunch by the river"]', '["Personal insurance","Alcohol","Tips"]', NULL, NULL, '1', '1', '8', NULL, NULL, '2026-04-26 14:38:49', '2026-04-27 04:32:28', NULL),
  ('3', 'adventure', 'Paragliding — Pokhara', 'paragliding-pokhara', 'Sarangkot, Pokhara', 'Gandaki Province', 'Soar over Phewa Lake with Annapurna panorama. Tandem flight from Sarangkot.', '<p>Pokhara is one of the world\'s best paragliding destinations. Your tandem flight launches from Sarangkot hill and glides over the turquoise Phewa Lake with Annapurna, Machhapuchhre, and Dhaulagiri filling the horizon. No experience required — your certified pilot does all the work.</p>', NULL, NULL, '90', NULL, '1', '0', '1', '15', 'easy', NULL, 'Sep-May', NULL, NULL, '["Annapurna panorama","Fewa Lake views","Tandem with certified pilot","GoPro footage available"]', '["Equipment","Certified pilot","Transport to Sarangkot"]', '["Video package (extra)","Hotel pickup"]', NULL, NULL, '0', '1', '2', NULL, NULL, '2026-04-26 14:38:49', '2026-04-27 05:28:15', NULL),
  ('4', 'trekking', 'Annapurna Base Camp Trek', 'annapurna-base-camp-trek', 'Annapurna Region, Kaski', 'Gandaki Province', '13-day classic trek to ABC at 4,130m. Rhododendron forests, glacier amphitheatre, mountain views.', '<p>The Annapurna Base Camp (ABC) trek is one of Nepal\'s most popular routes for good reason. You walk through Gurung villages, dense rhododendron forests that blaze red and pink in spring, past hot springs at Jhinu, and up to a dramatic 360° amphitheatre of peaks including Annapurna I (8,091m), Machhapuchhre, and Hiunchuli.</p><p>This is a moderate trek — challenging but achievable for anyone with reasonable fitness and proper acclimatisation.</p>', NULL, NULL, '950', NULL, '13', '12', '1', '15', 'moderate', '4130', 'Mar-May, Sep-Dec', 'Nayapul', 'Nayapul', '["4,130m base camp","Annapurna panorama","Rhododendron forests","Hot springs at Jhinu","Gurung villages"]', '["Licensed guide","Porter","Teahouse accommodation","All meals (B\\/L\\/D)","ACAP permit","TIMS card"]', '["International flights","Travel insurance","Personal gear","Tips"]', NULL, NULL, '1', '1', '6', NULL, NULL, '2026-04-26 14:38:49', '2026-04-27 05:29:55', NULL),
  ('5', 'trekking', 'Langtang Valley Trek', 'langtang-valley-trek', 'Langtang National Park, Rasuwa', 'Bagmati Province', '10-day trek through Tamang culture and high-altitude yak pastures near Tibet.', '<p>The Langtang Valley is one of Nepal\'s most accessible yet underrated treks. Just 68km north of Kathmandu, the valley offers stunning scenery, Tamang Buddhist culture, and views of Langtang Lirung (7,227m) without the crowds of the Annapurna or Everest regions.</p>', NULL, NULL, '750', NULL, '10', '9', '1', '15', 'moderate', '3870', 'Mar-May, Oct-Nov', 'Syabrubesi', 'Syabrubesi', '["Tamang culture","Yak pastures","Kyanjin Gompa","Cheese factory visit","Glacier views"]', '["Guide","Porter","Accommodation","All meals","National park permits"]', '["Flights to\\/from Kathmandu","Insurance","Personal expenses"]', NULL, NULL, '1', '1', '6', NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 15:58:26', NULL),
  ('6', 'valley_visit', 'Kathmandu Durbar Squares Tour', 'kathmandu-durbar-squares-tour', 'Kathmandu Valley', 'Bagmati Province', '2-day private guided tour of all three UNESCO-listed Durbar Squares.', '<p>Explore the heart of Nepal\'s ancient civilisation across three UNESCO World Heritage Durbar Squares — Kathmandu, Patan (Lalitpur), and Bhaktapur. Each square is a living museum of Newari architecture, medieval temples, royal palaces, and traditional craftwork still practiced today.</p>', NULL, NULL, '120', NULL, '2', '1', '1', '15', 'easy', NULL, 'Year-round', NULL, NULL, '["3 UNESCO sites","Expert local guide","Kumari Living Goddess courtyard","Pashupatinath Temple","Boudhanath Stupa"]', '["Private guide","Entry fees","Transport between sites","Lunch at Bhaktapur"]', '["Hotel accommodation","Dinner","Personal shopping"]', NULL, NULL, '1', '1', '3', NULL, NULL, '2026-04-26 14:38:49', '2026-04-29 18:15:13', NULL),
  ('7', 'national_park', 'Chitwan Jungle Safari — 3 Days', 'chitwan-jungle-safari-3-days', 'Chitwan National Park, Nawalpur', 'Bagmati / Madhesh Province', 'Jeep safari, elephant breeding centre, canoe ride, and Tharu culture in Nepal\'s most famous national park.', '<p>Chitwan National Park is a UNESCO World Heritage Site and home to one-horned rhinoceroses, Bengal tigers, gharial crocodiles, and over 600 bird species. Our 3-day package includes jeep safaris at dawn and dusk (best for wildlife), a canoe ride on the Rapti River, cultural visits to Tharu villages, and a visit to the elephant breeding centre.</p>', NULL, NULL, '350', NULL, '3', '2', '1', '15', 'easy', NULL, 'Oct-Mar', NULL, NULL, '["One-horned rhino sightings","Tiger territory jeep safari","Canoe river ride","Tharu cultural program","Bird watching"]', '["Accommodation at jungle lodge","All meals","Jeep safaris","Park entry fees","Naturalist guide"]', '["Transport to\\/from Chitwan","Alcohol","Tips","Personal insurance"]', NULL, NULL, '1', '1', '1', NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 16:50:04', NULL),
  ('8', 'wildlife_reserve', 'Bardia Wildlife Reserve — Tiger Trek', 'bardia-wildlife-tiger-trek', 'Bardia National Park, Bardiya', 'Lumbini Province', '5-day deep wilderness safari in Nepal\'s least-visited tiger reserve. Better odds than Chitwan.', '<p>Bardia National Park is Nepal\'s largest and most pristine wildlife reserve, with significantly higher tiger density than Chitwan. Because it receives far fewer visitors, wildlife encounters here feel genuinely wild. Walk with a naturalist through tall elephant grass, riverine forest, and open savannahs. Most visitors see rhino, deer, and monkeys. Tiger sightings are rare but real.</p>', NULL, NULL, '580', NULL, '5', '4', '1', '15', 'easy', NULL, 'Oct-Apr', NULL, NULL, '["Best tiger chances in Nepal","Pristine wilderness","Walking safaris","Karnali River rafting option","Dolphin spotting"]', '["Eco-lodge accommodation","All meals","Walking safaris","Park fees","Expert naturalist"]', '["Flights to Nepalgunj","Personal insurance","Alcohol"]', NULL, NULL, '0', '1', '0', NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 14:38:49', NULL),
  ('9', 'lake', 'Rara Lake Trek — Nepal\'s Hidden Gem', 'rara-lake-trek', 'Rara National Park, Mugu', 'Karnali Province', '12-day expedition to Nepal\'s largest and most remote lake at 2,990m. True wilderness.', '<p>Rara Lake is Nepal\'s largest and most remote lake — a jewel of deep blue surrounded by conifer forests and snow-capped peaks in the far northwest. Because of its remoteness (flights from Kathmandu to Jumla, then trek), very few tourists ever reach it. Those who do are rewarded with absolute silence, pristine nature, and one of the most beautiful lake settings on earth.</p>', NULL, NULL, '1650', NULL, '12', '11', '1', '15', 'challenging', '3731', 'Apr-Jun, Sep-Nov', 'Jumla', 'Jumla', '["Nepal\'s largest lake","Rara National Park","Snow leopard habitat","Remote villages","Untouched wilderness"]', '["Domestic flights KTM-Jumla-KTM","Guide & porter","Accommodation","All meals","Park permits"]', '["International flights","Travel insurance","Personal gear","Tips"]', NULL, NULL, '1', '1', '2', NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 15:38:58', NULL),
  ('10', 'lake', 'Fewa Lake Pokhara — Kayaking & Reflection', 'fewa-lake-pokhara-kayaking', 'Phewa Lake, Pokhara', 'Gandaki Province', '2-day Pokhara experience: kayaking on Fewa, Barahi Island temple, Annapurna reflections.', '<p>Fewa Lake is one of Nepal\'s most beautiful bodies of water — a 4.4 km² lake with perfect reflections of the Annapurna massif on calm mornings. Kayak at sunrise, visit the Tal Barahi temple on the island, cycle the lakeside, and watch the mountains from the shore at dusk.</p>', NULL, NULL, '85', NULL, '2', '1', '1', '15', 'easy', NULL, 'Sep-May', NULL, NULL, '["Annapurna reflections","Sunrise kayaking","Island temple visit","Lakeside cycling","Mountain photography"]', '["Kayak hire","Guide","Lakeside hotel 1 night","Breakfast"]', '["Lunch\\/dinner","Paragliding (can be added)","Personal transport"]', NULL, NULL, '0', '1', '0', NULL, NULL, '2026-04-26 14:38:49', '2026-04-26 14:38:49', NULL),
  ('15', 'adventure', 'dcsdfdf', 'dcsdfdf', 'dsfsdf', 'dsf sd', 'dfsf sdf sdfsdf', 'dsf sdf sdfasdfasdfsadfad', NULL, NULL, '122.95', NULL, '1', '0', '1', '15', NULL, NULL, NULL, NULL, NULL, '["sd fsd fsadf"]', '["sd fsd fasd fasdf"]', '["sd fsd fsad fsad"]', NULL, NULL, '0', '1', '9', 'sadf asd f', 'sdfsda fsad fas', '2026-04-29 17:58:54', '2026-04-29 18:18:42', '1');
