INSERT INTO `slides` (`id`, `image`, `tag`, `title`, `desc`, `btn_text`, `btn_link`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
  ('1', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?w=1600&q=80', '🇳🇵 Nepal\'s #1 curated travel platform', 'Adventure, culture &\nHimalayan wilderness', 'Book treks, adventures, wildlife safaris, lake expeditions and cultural tours — all curated by a local Nepali with insider knowledge.', 'Browse all experiences', '/packages', '1', '1', '2026-04-26 17:11:22', '2026-04-26 17:11:22'),
  ('2', 'https://images.unsplash.com/photo-1542224566-6e85f2e6772f?w=1600&q=80', 'Heritage', 'Discover Ancient\nTemples & Culture', 'Wander through the historic durbar squares and mystical temples of the Kathmandu Valley.', 'Valley Visits', '/packages/valley-visits', '2', '1', '2026-04-26 17:11:22', '2026-04-26 17:11:22'),
  ('3', 'https://images.unsplash.com/photo-1588614959060-4d144f28b207?w=1600&q=80', 'Wildlife', 'Into the Wild:\nJungle Safaris', 'Encounter rhinos, tigers, and elephants in the dense sub-tropical jungles of Chitwan and Bardia.', 'Wildlife Packages', '/packages/wildlife', '3', '1', '2026-04-26 17:11:22', '2026-04-26 17:11:22'),
  ('4', 'https://images.unsplash.com/photo-1586861214151-5182103f6f34?w=1600&q=80', 'Adventure', 'Thrilling Heights &\nAdrenaline Rushes', 'Paragliding over Phewa Lake, bungee jumping, and white-water rafting for the ultimate thrill seekers.', 'Adventure Packages', '/packages/adventure', '4', '1', '2026-04-26 17:11:22', '2026-04-26 17:11:22'),
  ('5', 'https://images.unsplash.com/photo-1627896157734-4bcdd68b6a67?w=1600&q=80', 'Nature', 'Serene Lakes &\nHidden Paradises', 'Reflect by the pristine waters of Rara, Phoksundo, and Gokyo high in the Himalayas.', 'Lake Expeditions', '/packages/lakes', '5', '1', '2026-04-26 17:11:22', '2026-04-26 17:11:22');
INSERT INTO `static_pages` (`id`, `slug`, `title`, `content`, `meta_description`, `show_in_footer`, `sort_order`, `created_at`, `updated_at`) VALUES
  ('1', 'about-us', 'About Us', '<h2>Welcome to TrekBazar Nepal</h2>\n<p>TrekBazar is Nepal\'s premier online travel marketplace, connecting adventurers from around the world with authentic, locally-guided experiences in the heart of the Himalayas.</p>\n\n<h3>Our Story</h3>\n<p>Founded in Kathmandu, TrekBazar was born from a passion for responsible tourism and a deep love for Nepal\'s incredible landscapes, culture, and people. We believe that the best travel experiences come from genuine local knowledge and meaningful connections.</p>\n\n<h3>What We Offer</h3>\n<ul>\n  <li><strong>Trekking & Adventure</strong> — From Everest Base Camp to remote Himalayan trails</li>\n  <li><strong>Cultural Experiences</strong> — UNESCO World Heritage sites, festivals, and local homestays</li>\n  <li><strong>Wildlife & Nature</strong> — Chitwan, Bardia, and Nepal\'s stunning national parks</li>\n  <li><strong>Gear Shop</strong> — Authentic Nepali trekking gear and souvenirs</li>\n</ul>\n\n<h3>Our Mission</h3>\n<p>We are committed to sustainable, community-based tourism that benefits local guides, porters, and villages across Nepal. Every booking you make directly supports Nepali families and conservation efforts.</p>\n\n<h3>Get In Touch</h3>\n<p>Have questions? Our team of local experts is always happy to help you plan your perfect Nepal adventure.</p>\n<p>📧 <a href="mailto:hello@trekbazar.com">hello@trekbazar.com</a><br>📞 +977-1-XXXXXXX<br>📍 Thamel, Kathmandu, Nepal</p>', 'Learn about TrekBazar Nepal — your trusted partner for authentic Himalayan travel experiences.', '1', '1', '2026-04-27 04:30:53', '2026-04-27 04:30:53'),
  ('2', 'privacy-policy', 'Privacy Policy', '<h2>Privacy Policy</h2>\n<p><em>Last updated: April 2026</em></p>\n\n<p>TrekBazar Nepal ("we", "us", "our") is committed to protecting your privacy. This Privacy Policy explains how we collect, use, disclose, and safeguard your information when you visit our website.</p>\n\n<h3>Information We Collect</h3>\n<ul>\n  <li><strong>Personal Information:</strong> Name, email address, phone number when you register or make a booking</li>\n  <li><strong>Payment Information:</strong> Processed securely by our payment partners; we do not store card details</li>\n  <li><strong>Usage Data:</strong> Pages visited, time spent, browser type, IP address for analytics</li>\n</ul>\n\n<h3>How We Use Your Information</h3>\n<ul>\n  <li>To process bookings and purchases</li>\n  <li>To send booking confirmations and travel updates</li>\n  <li>To improve our services and website experience</li>\n  <li>To send promotional emails (you may opt out at any time)</li>\n</ul>\n\n<h3>Data Security</h3>\n<p>We implement appropriate technical and organisational measures to protect your personal information against unauthorised access, alteration, or destruction.</p>\n\n<h3>Third-Party Services</h3>\n<p>We may use third-party services (Google Analytics, payment processors) that collect data under their own privacy policies.</p>\n\n<h3>Your Rights</h3>\n<p>You have the right to access, correct, or delete your personal data. Contact us at <a href="mailto:privacy@trekbazar.com">privacy@trekbazar.com</a> to exercise these rights.</p>\n\n<h3>Contact</h3>\n<p>For privacy-related enquiries: <a href="mailto:privacy@trekbazar.com">privacy@trekbazar.com</a></p>', 'TrekBazar Nepal Privacy Policy — how we collect, use and protect your personal data.', '1', '2', '2026-04-27 04:30:53', '2026-04-27 04:30:53'),
  ('3', 'terms-of-service', 'Terms of Service', '<h2>Terms of Service</h2>\n<p><em>Last updated: April 2026</em></p>\n\n<p>By accessing or using TrekBazar Nepal ("the Service"), you agree to be bound by these Terms of Service. Please read them carefully.</p>\n\n<h3>1. Acceptance of Terms</h3>\n<p>By using our website, you confirm that you are at least 18 years old and agree to these terms. If you do not agree, please do not use our services.</p>\n\n<h3>2. Bookings & Payments</h3>\n<ul>\n  <li>All bookings are subject to availability and confirmation</li>\n  <li>Prices are displayed in USD unless otherwise stated</li>\n  <li>Full payment is required to confirm a booking</li>\n  <li>TrekBazar acts as an agent between you and local service providers</li>\n</ul>\n\n<h3>3. Cancellation Policy</h3>\n<ul>\n  <li><strong>30+ days before departure:</strong> Full refund minus processing fees</li>\n  <li><strong>15–29 days:</strong> 50% refund</li>\n  <li><strong>0–14 days:</strong> No refund</li>\n</ul>\n\n<h3>4. Traveller Responsibilities</h3>\n<p>You are responsible for ensuring you have valid travel documents, travel insurance, and physical fitness appropriate for your chosen activity.</p>\n\n<h3>5. Limitation of Liability</h3>\n<p>TrekBazar shall not be liable for injury, loss, or damage arising from participation in activities. All adventure activities carry inherent risks.</p>\n\n<h3>6. Governing Law</h3>\n<p>These terms are governed by the laws of Nepal. Disputes shall be subject to the exclusive jurisdiction of courts in Kathmandu.</p>\n\n<h3>Contact</h3>\n<p>For legal enquiries: <a href="mailto:legal@trekbazar.com">legal@trekbazar.com</a></p>', 'TrekBazar Nepal Terms of Service — the rules and guidelines for using our platform.', '1', '3', '2026-04-27 04:30:53', '2026-04-27 04:30:53'),
  ('4', 'contact-us', 'Contact Us', '<h2>Contact Us</h2>\n<p>We\'d love to hear from you! Whether you have a question about a package, need help with a booking, or just want to learn more about Nepal — our team is here to help.</p>\n\n<h3>📍 Our Office</h3>\n<p>TrekBazar Nepal<br>Thamel, Kathmandu 44600<br>Nepal</p>\n\n<h3>📞 Phone & WhatsApp</h3>\n<p>+977-1-XXXXXXX<br>WhatsApp: +977-98XXXXXXXX<br>Available: Sunday–Friday, 9am–6pm NPT</p>\n\n<h3>📧 Email</h3>\n<ul>\n  <li>General enquiries: <a href="mailto:hello@trekbazar.com">hello@trekbazar.com</a></li>\n  <li>Bookings: <a href="mailto:bookings@trekbazar.com">bookings@trekbazar.com</a></li>\n  <li>Support: <a href="mailto:support@trekbazar.com">support@trekbazar.com</a></li>\n</ul>\n\n<h3>🕐 Response Time</h3>\n<p>We aim to respond to all enquiries within 24 hours during business days.</p>', 'Get in touch with TrekBazar Nepal — we\'re here to help plan your perfect Nepal adventure.', '1', '4', '2026-04-27 04:30:53', '2026-04-27 04:30:53');
